    assert obj.val == 42


def test_instanceproperty_setter_deleter():
    class C:
        def __init__(self):
            self._v = 1

        @instanceproperty
        def v(self):
            return self._v

        @v.setter
        def v(self, value):
            self._v = value

        @v.deleter
        def v(self):
            self._v = -1

    c = C()
    assert c.v == 1
    c.v = 5
    assert c.v == 5
    del c.v
    assert c.v == -1


